UPDATE products AS p
SET description = v.description,
    updated_at = NOW()
FROM (VALUES
('TEST-MLBB-001','TEST ONLY • FIXTURE UJI INTERNAL • BUKAN PRODUK KOMERSIAL.\n\nKategori: Mobile Legends: Bang Bang. Tier tampilan: Silver. Tujuan: menguji kartu produk, detail produk, status stok, reservasi, invoice Telegram Stars, konfirmasi webhook, dan alur delivery.\n\nPemenuhan: SERVICE_INSTRUCTIONS. Persediaan berisi satu payload dummy terenkripsi yang secara eksplisit bukan kode redeem, tidak dapat ditukarkan, dan tidak dapat digunakan untuk login atau mengambil alih akun.\n\nHarga uji: 1 XTR. Jika invoice produksi diselesaikan, Telegram tetap menagih 1 Telegram Star sungguhan. Modal internal fixture: 0 XTR.\n\nAktivasi hanya melalui ruang uji Owner dan satu fixture dapat aktif pada satu waktu. Jangan gunakan data fixture sebagai inventaris atau penawaran komersial.'),
('TEST-ROBLOX-001','TEST ONLY • FIXTURE UJI INTERNAL • BUKAN PRODUK KOMERSIAL.\n\nKategori: Roblox. Tier tampilan: Gold. Tujuan: menguji kartu produk, detail produk, status stok, reservasi, invoice Telegram Stars, konfirmasi webhook, dan alur delivery.\n\nPemenuhan: SERVICE_INSTRUCTIONS. Persediaan berisi satu payload dummy terenkripsi yang secara eksplisit bukan kode redeem, tidak dapat ditukarkan, dan tidak dapat digunakan untuk login atau mengambil alih akun.\n\nHarga uji: 1 XTR. Jika invoice produksi diselesaikan, Telegram tetap menagih 1 Telegram Star sungguhan. Modal internal fixture: 0 XTR.\n\nAktivasi hanya melalui ruang uji Owner dan satu fixture dapat aktif pada satu waktu. Jangan gunakan data fixture sebagai inventaris atau penawaran komersial.'),
('TEST-FREEFIRE-001','TEST ONLY • FIXTURE UJI INTERNAL • BUKAN PRODUK KOMERSIAL.\n\nKategori: Free Fire. Tier tampilan: Platinum. Tujuan: menguji kartu produk, detail produk, status stok, reservasi, invoice Telegram Stars, konfirmasi webhook, dan alur delivery.\n\nPemenuhan: SERVICE_INSTRUCTIONS. Persediaan berisi satu payload dummy terenkripsi yang secara eksplisit bukan kode redeem, tidak dapat ditukarkan, dan tidak dapat digunakan untuk login atau mengambil alih akun.\n\nHarga uji: 1 XTR. Jika invoice produksi diselesaikan, Telegram tetap menagih 1 Telegram Star sungguhan. Modal internal fixture: 0 XTR.\n\nAktivasi hanya melalui ruang uji Owner dan satu fixture dapat aktif pada satu waktu. Jangan gunakan data fixture sebagai inventaris atau penawaran komersial.'),
('TEST-GENSHIN-001','TEST ONLY • FIXTURE UJI INTERNAL • BUKAN PRODUK KOMERSIAL.\n\nKategori: Genshin Impact. Tier tampilan: Silver. Tujuan: menguji kartu produk, detail produk, status stok, reservasi, invoice Telegram Stars, konfirmasi webhook, dan alur delivery.\n\nPemenuhan: SERVICE_INSTRUCTIONS. Persediaan berisi satu payload dummy terenkripsi yang secara eksplisit bukan kode redeem, tidak dapat ditukarkan, dan tidak dapat digunakan untuk login atau mengambil alih akun.\n\nHarga uji: 1 XTR. Jika invoice produksi diselesaikan, Telegram tetap menagih 1 Telegram Star sungguhan. Modal internal fixture: 0 XTR.\n\nAktivasi hanya melalui ruang uji Owner dan satu fixture dapat aktif pada satu waktu. Jangan gunakan data fixture sebagai inventaris atau penawaran komersial.')
